const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry definitions
  var reykjavik = ee.Geometry.Point([-21.827774, 64.128288]).buffer(5000); // 5 km buffer
  var snaefellsnes = ee.Geometry.Point([-23.561, 64.805]).buffer(5000); // 5 km buffer

  // 2. Time range
  var startDate = '2016-01-01';
  var endDate = '2016-12-31';

  // 3. Data acquisition: VIIRS monthly nighttime lights
  var viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(startDate, endDate)
    .select('avg_rad');

  // Check collection size
  var count = viirs.size().getInfo();
  if (count === 0) {
    console.log('No VIIRS images found for 2016.');
    console.log('<answer>C1</answer>');
    return;
  }
  console.log('2016 VIIRS Images:', count);

  // 4. Create a mean composite for the year
  var meanImage = viirs.mean();

  // 5. Function to compute mean radiance and pixel count for a region
  function getStats(geometry, name) {
    // First, get pixel count (valid pixels)
    var countImg = meanImage.select('avg_rad').mask();
    var pixelCount = countImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    }).get('avg_rad').getInfo();

    // Then, get mean radiance
    var meanVal = meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    }).get('avg_rad').getInfo();

    return {name: name, count: pixelCount, mean: meanVal};
  }

  var statsReykjavik = getStats(reykjavik, 'Reykjavik');
  var statsSnaefellsnes = getStats(snaefellsnes, 'Snaefellsnes');

  console.log('Reykjavik - Pixel count:', statsReykjavik.count, 'Mean radiance:', statsReykjavik.mean);
  console.log('Snaefellsnes - Pixel count:', statsSnaefellsnes.count, 'Mean radiance:', statsSnaefellsnes.mean);

  // 6. Check for no valid pixels (C2)
  if (statsReykjavik.count === 0 || statsSnaefellsnes.count === 0) {
    console.log('No valid pixels in one or both regions.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Validate results: check for NaN or unrealistic values
  if (statsReykjavik.mean === null || statsSnaefellsnes.mean === null ||
      isNaN(statsReykjavik.mean) || isNaN(statsSnaefellsnes.mean)) {
    console.log('Invalid mean values (NaN/null).');
    console.log('<answer>C3</answer>');
    return;
  }

  // Typical VIIRS radiance values are between 0 and ~100 nW/cm²/sr
  if (statsReykjavik.mean < 0 || statsReykjavik.mean > 100 ||
      statsSnaefellsnes.mean < 0 || statsSnaefellsnes.mean > 100) {
    console.log('Mean radiance out of expected range (0-100).');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Compare and output final answer
  if (statsReykjavik.mean > statsSnaefellsnes.mean) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
